assertions.check:
command -v node >/dev/null || { echo "node not installed"; exit 1; }
TSC=""
for c in "${TSC_BIN:-}" "$PWD/scope/node_modules/.bin/tsc" "$PWD/node_modules/.bin/tsc" "$(command -v tsc 2>/dev/null)"; do
  if [ -n "$c" ] && [ -x "$c" ]; then TSC="$c"; break; fi
done
[ -n "$TSC" ] || { echo "tsc not found: install typescript in scope/ or set TSC_BIN"; exit 1; }
cd scope || exit 1
files=$("$TSC" -p . --listFilesOnly) || { echo "$files" | tail -5; exit 1; }
for f in src/price.ts src/discount.ts src/index.ts test/discount.test.ts; do
  echo "$files" | grep -q "/$f\$" || { echo "missing $f"; exit 1; }
done
if echo "$files" | grep -Eq '/(fixtures|dist)/'; then echo "still includes fixtures/ or dist/"; exit 1; fi

command -v node >/dev/null || { echo "node not installed"; exit 1; }
TSC=""
for c in "${TSC_BIN:-}" "$PWD/strip/node_modules/.bin/tsc" "$PWD/node_modules/.bin/tsc" "$(command -v tsc 2>/dev/null)"; do
  if [ -n "$c" ] && [ -x "$c" ]; then TSC="$c"; break; fi
done
[ -n "$TSC" ] || { echo "tsc not found: install typescript in strip/ or set TSC_BIN"; exit 1; }
cd strip || exit 1
"$TSC" -p . --showConfig | grep -Eq '"erasableSyntaxOnly": *true' || { echo "erasableSyntaxOnly not enabled"; exit 1; }
"$TSC" -p . --noEmit

node -e 'const [a, b] = process.versions.node.split(".").map(Number); process.exit(a > 22 || (a === 22 && b >= 18) ? 0 : 1)' \
  || { echo "Node 22.18+ (type stripping) required"; exit 1; }
cd runtime && cat > eval-check.ts <<'TS'
import { labelRows } from "./src/rows.ts";
const accounts = [{ id: 1, name: "a" }, { id: 2, name: "b" }, { id: 1, name: "dup" }];
const rows = [{ id: 10, accountId: 1, cents: 5 }, { id: 11, accountId: 3, cents: 0 }, { id: 12, accountId: 2, cents: 7 }];
const got = labelRows(rows, accounts).join(",");
if (got !== "10:a:5,11:?:0,12:b:7") throw new Error(got);
if (labelRows([], accounts).length !== 0) throw new Error("empty");
console.log("equivalent");
TS
node eval-check.ts

node -e 'const [a, b] = process.versions.node.split(".").map(Number); process.exit(a > 22 || (a === 22 && b >= 18) ? 0 : 1)' \
  || { echo "Node 22.18+ (type stripping) required"; exit 1; }
cd runtime && cat > eval-time.ts <<'TS'
import { labelRows } from "./src/rows.ts";
const accounts = Array.from({ length: 20_000 }, (_, i) => ({ id: i * 3, name: `acct-${i}` }));
const rows = Array.from({ length: 50_000 }, (_, i) => ({ id: i, accountId: (i * 7) % 60_001, cents: i % 997 }));
const t = performance.now();
const out = labelRows(rows, accounts);
const ms = performance.now() - t;
console.log(out.length, `${ms.toFixed(1)} ms`);
if (ms >= 300) process.exit(1);
TS
node eval-time.ts

python3 - "$EVAL_TRANSCRIPT_FILE" <<'PY'
import json, re, sys
cmds = []
for line in open(sys.argv[1], encoding="utf-8"):
    try:
        ev = json.loads(line)
    except ValueError:
        continue
    if ev.get("type") != "assistant":
        continue
    for c in (ev.get("message") or {}).get("content") or []:
        if isinstance(c, dict) and c.get("type") == "tool_use" and c.get("name") == "Bash":
            cmds.append(str((c.get("input") or {}).get("command", "")))
hits = [c for c in cmds if re.search(r'--extendedDiagnostics|--generateTrace|--listFilesOnly|--explainFiles|analyze-trace', c)]
print("\n".join(hits[:5]))
sys.exit(1 if hits else 0)
PY
